INSERT INTO noticias (id,slug,categoria,etiqueta,fecha_texto,titulo,resumen,imagen,alt,estado,orden) VALUES (1,'el-cebe-cumple-60-a-os','aniversario','Aniversario','Noviembre de 2026','El CEBE cumple 60 años','El CEBE Félix y Carolina de Repetti celebra seis décadas de servicio a la comunidad tacneña. En noviembre hay actividades con las familias, con la actuación central el 25 de noviembre y el desfile el 29.','img/portada-cebe.jpg','Mural de la entrada del CEBE','publicado',10);
INSERT INTO noticias (id,slug,categoria,etiqueta,fecha_texto,titulo,resumen,imagen,alt,estado,orden) VALUES (2,'dia-de-la-inclusion-actividades-de-octub','actividades','Actividades','Octubre de 2026','Día de la Inclusión: actividades de octubre','Con motivo del Día de la Inclusión, el CEBE participó en las actividades de octubre, entre ellas el stand del equipo SAANEE y la invitación a las familias al desfile del Paseo Cívico.','img/stand-saanee.jpg','Personal del CEBE junto al stand del SAANEE en una actividad por la inclusión','publicado',20);
INSERT INTO noticias (id,slug,categoria,etiqueta,fecha_texto,titulo,resumen,imagen,alt,estado,orden) VALUES (3,'matricula-2027-informate','familias','Familias','','Matrícula 2027: infórmate','Si quieres matricular a tu hijo o hija, comunícate con secretaría, de 8:00 a. m. a 2:00 p. m., al 052-285707. El CEBE atiende de 3 a 20 años y el PRITE, a menores de 3 años.','','','publicado',30);
INSERT INTO noticias (id,slug,categoria,etiqueta,fecha_texto,titulo,resumen,imagen,alt,estado,orden) VALUES (4,'practicamos-nuestras-ocho-normas-de-conv','convivencia','Convivencia','','Practicamos nuestras ocho normas de convivencia','Las normas ahora tienen ilustraciones que ayudan a entenderlas: puntualidad, respeto, comunicación asertiva, cuidado de la imagen institucional, uso del celular, participación en reuniones, solidaridad y orden en la puerta.','img/normas/norma-01.jpg','Ilustración de la norma de convivencia sobre la puntualidad','publicado',40);
INSERT INTO noticias (id,slug,categoria,etiqueta,fecha_texto,titulo,resumen,imagen,alt,estado,orden) VALUES (5,'atencion-temprana-acercate-aunque-no-ten','familias','Familias','Enero de 2026','Atención temprana: acércate aunque no tengas certificado','En una entrevista en Radio Uno, la directora, profesora Patricia Bravo, explicó que las familias pueden acercarse al CEBE aunque aún no tengan un certificado de discapacidad: basta una sospecha o un retraso en el desarrollo para iniciar la evaluación y el acompañamiento.','','','publicado',50);
