INSERT INTO avisos (id,slug,etiqueta,titulo,texto,cierre,firma,destacado,archivado,estado,orden) VALUES (1,'aniversario-60','Comisión de Aniversario','¡Estamos de aniversario! 60 años','Con motivo de nuestro 60.° aniversario, celebramos seis décadas de compromiso y servicio a nuestra comunidad. Estas son las actividades programadas. ¡Juntos hagamos de esta celebración un momento especial e inolvidable!','¡Feliz 60.° aniversario de nuestro querido CEBE!','',1,0,'publicado',10);
