INSERT INTO preguntas (id,pregunta,respuesta,estado,orden) VALUES (1,'¿A quiénes atiende el CEBE?','A estudiantes de 3 a 20 años con discapacidad intelectual severa o multidiscapacidad, que requieren apoyos permanentes y especializados. Atendemos los niveles de Inicial y Primaria.','publicado',10);
INSERT INTO preguntas (id,pregunta,respuesta,estado,orden) VALUES (2,'¿Qué es el TVA (Tránsito a la Vida Adulta)?','Es la etapa que se trabaja de cuarto a sexto grado de primaria (de 12 a 20 años) para que cada estudiante logre la mayor autonomía posible y se prepare para su vida familiar, social y laboral. Tiene tres etapas de 3 años: básico, intermedio y avanzado.','publicado',20);
INSERT INTO preguntas (id,pregunta,respuesta,estado,orden) VALUES (3,'¿A qué hora es el ingreso y la salida de los estudiantes?','El ingreso de Primaria es a las 8:00 a. m. y el de Inicial, a las 8:30 a. m. La salida es de 12:45 a 1:00 p. m. Pedimos puntualidad. Recuerda también nuestras normas de convivencia para el ingreso y la salida.','publicado',30);
INSERT INTO preguntas (id,pregunta,respuesta,estado,orden) VALUES (4,'¿Qué es el equipo interdisciplinario?','Es el grupo de profesionales no docentes del CEBE (psicología, trabajo social y terapia) que trabajan junto con las docentes para que cada estudiante aprenda con los apoyos que necesita, y que acompañan a las familias.','publicado',40);
INSERT INTO preguntas (id,pregunta,respuesta,estado,orden) VALUES (5,'¿Qué es el PRITE?','Es el Programa de Intervención Temprana, para niñas y niños menores de 3 años con discapacidad o en riesgo de adquirirla. Atender a tiempo ayuda a prevenir retrasos en su desarrollo.','publicado',50);
INSERT INTO preguntas (id,pregunta,respuesta,estado,orden) VALUES (6,'¿Qué es el SAANEE?','Es el Servicio de Apoyo y Asesoramiento para la Atención de Necesidades Educativas Especiales. Asesora a otras instituciones educativas para incluir a estudiantes con discapacidad, TEA o altas capacidades.','publicado',60);
INSERT INTO preguntas (id,pregunta,respuesta,estado,orden) VALUES (7,'¿Qué son la EPP y el PEP?','La Evaluación Psicopedagógica (EPP) permite conocer las fortalezas de cada estudiante, las barreras que enfrenta y los apoyos que necesita. Con esa información, los docentes elaboran el Plan Educativo Personalizado (PEP), una respuesta educativa individual.','publicado',70);
INSERT INTO preguntas (id,pregunta,respuesta,estado,orden) VALUES (8,'¿Dónde queda el CEBE?','En el distrito de Pocollay, Tacna: Av. Industrial S/N y calle Carolina Repetti S/N.','publicado',80);
INSERT INTO preguntas (id,pregunta,respuesta,estado,orden) VALUES (9,'¿Cómo me comunico con el CEBE?','Secretaría atiende de 8:00 a. m. a 2:00 p. m. Teléfono: 052-285707. Correo: cebe.repetti.2020@gmail.com. También puede escribirnos desde la página de Contacto.','publicado',90);
INSERT INTO preguntas (id,pregunta,respuesta,estado,orden) VALUES (10,'¿Cómo solicito información para matricular a mi hijo o hija?','Comuníquese con secretaría, de 8:00 a. m. a 2:00 p. m., al 052-285707.','publicado',100);
INSERT INTO preguntas (id,pregunta,respuesta,estado,orden) VALUES (11,'¿Dónde veo los comunicados y las novedades?','En la sección de Comunicados y en nuestra página de Facebook.','publicado',110);
INSERT INTO preguntas (id,pregunta,respuesta,estado,orden) VALUES (12,'¿Qué normas de convivencia se practican?','Son ocho normas, como la puntualidad, el respeto y la comunicación asertiva.','publicado',120);
INSERT INTO preguntas (id,pregunta,respuesta,estado,orden) VALUES (13,'¿Qué hago si conozco un caso de violencia escolar o familiar?','Comuníquelo a la Dirección del CEBE o llame a la Línea 100.','publicado',130);
